package org.opensourcepingpong.competition.algorithm;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class AlgorithmsTest { @Test void knockoutSizesAndReproducibility(){for(int n:new int[]{2,3,4,5,7,8,9,13,16,17,31,32,33,64}){List<Integer> p=new ArrayList<>();for(int i=0;i<n;i++)p.add(i);int size=SingleEliminationBracketGenerator.bracketSize(n);var slots=SingleEliminationBracketGenerator.arrange(p,9);assertTrue(size>=n);assertEquals(size-n,slots.stream().filter(Objects::isNull).count());assertEquals(n,new HashSet<>(slots.stream().filter(Objects::nonNull).toList()).size());assertEquals(SingleEliminationBracketGenerator.arrange(p,9),SingleEliminationBracketGenerator.arrange(p,9));}} @Test void roundRobinPairsExactlyOnce(){for(int n:new int[]{3,4,5,6,7,8}){List<Integer> p=new ArrayList<>();for(int i=0;i<n;i++)p.add(i);var rounds=RoundRobinScheduleGenerator.generate(p);Set<String> pairs=new HashSet<>();for(var round:rounds){Set<Integer> seen=new HashSet<>();for(var pair:round){assertTrue(seen.add(pair.a()));assertTrue(seen.add(pair.b()));pairs.add(Math.min(pair.a(),pair.b())+":"+Math.max(pair.a(),pair.b()));}}assertEquals(n*(n-1)/2,pairs.size());}} @Test void scores(){for(var g:List.of(new ScoreValidator.Game(11,0),new ScoreValidator.Game(11,9),new ScoreValidator.Game(12,10),new ScoreValidator.Game(15,13)))assertEquals(0,ScoreValidator.winner(g));for(var g:List.of(new ScoreValidator.Game(10,8),new ScoreValidator.Game(11,10),new ScoreValidator.Game(12,11)))assertThrows(IllegalArgumentException.class,()->ScoreValidator.winner(g));assertEquals(0,ScoreValidator.matchWinner(3,List.of(new ScoreValidator.Game(11,9),new ScoreValidator.Game(12,10))));assertEquals(0,ScoreValidator.matchWinner(5,List.of(new ScoreValidator.Game(11,9),new ScoreValidator.Game(9,11),new ScoreValidator.Game(11,9),new ScoreValidator.Game(12,10))));assertEquals(0,ScoreValidator.matchWinner(7,List.of(new ScoreValidator.Game(11,9),new ScoreValidator.Game(9,11),new ScoreValidator.Game(11,9),new ScoreValidator.Game(9,11),new ScoreValidator.Game(11,9),new ScoreValidator.Game(12,10))));assertThrows(IllegalArgumentException.class,()->ScoreValidator.matchWinner(3,List.of(new ScoreValidator.Game(11,9))));} }
